// Fixed code: Validate and sanitize the URL to prevent SSRF attacks
import java.net.URL;
import java.net.MalformedURLException;

public class GoodExample {
    public static void main(String[] args) {
        String userInput = "http://internal-api:8080/secret-data"; // Simulated user input
        try {
            // Validate the URL to ensure it's external and doesn't point to internal services
            if (isValidExternalUrl(userInput)) {
                URL url = new URL(userInput);
                System.out.println("Loading resource from: " + url.toString());
            } else {
                System.out.println("Invalid or internal URL detected. Access denied.");
            }
        } catch (MalformedURLException e) {
            System.out.println("Error loading resource: " + e.getMessage());
        }
    }

    // Helper method to check if the URL is external
    private static boolean isValidExternalUrl(String urlStr) {
        try {
            URL url = new URL(urlStr);
            // Check if the host is not in the internal network
            return !url.getHost().startsWith("localhost") && 
                   !url.getHost().startsWith("127.0.0.1") &&
                   !url.getHost().startsWith("internal-") &&
                   !url.getHost().startsWith("192.168.") &&
                   !url.getHost().startsWith("10.");
        } catch (MalformedURLException e) {
            return false;
        }
    }
}
