```java
// Corretto: uso sicuro dell'API Java con validazione degli input
import java.util.Scanner;

public class Example {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String userInput = scanner.nextLine(); // Input non filtrato

        // Validazione e sanitizzazione dell'input prima di eseguire un comando
        if (isValidCommand(userInput)) {
            try {
                Process process = Runtime.getRuntime().exec(userInput);
                int exitCode = process.waitFor();
                System.out.println("Comando eseguito, codice di uscita: " + exitCode);
            } catch (Exception e) {
                e.printStackTrace();
            }
        } else {
            System.out.println("Comando non valido o non autorizzato.");
        }
    }

    // Funzione per verificare che l'input sia un comando consentito
    private static boolean isValidCommand(String command) {
        // Esempio semplice: permetti solo comandi specifici
        return command != null && 
               (command.equals("ls") || command.equals("pwd") || command.equals("date"));
    }
}
```

